@Test
void bruttoGueltig() {
  // Arrange
  Rechner r = new Rechner();
  // Act
  double ist = r.brutto(100.0);
  // Assert
  assertEquals(119.0, ist, 0.001);
}

@Test
void bruttoNegativWirft() {
  // Arrange
  Rechner r = new Rechner();
  // Act und Assert
  assertThrows(IllegalArgumentException.class,
      () -> r.brutto(-5.0));
}
